const EF_STUB = {
  type: 'custom:energiefluss-card',
  pv: { entity: 'sensor.pv_power', secondary_entity: 'sensor.pv_energy_today' },
  grid: { entity: 'sensor.grid_power', secondary_entity: 'sensor.grid_import_today', secondary_entity_2: 'sensor.grid_export_today' },
  battery: {
    soc_entity: 'sensor.battery_soc',
    charge_entity: 'sensor.battery_charge_power',
    discharge_entity: 'sensor.battery_discharge_power'
  },
  home: { entity: 'sensor.house_consumption', secondary_entity: 'sensor.house_consumption_today' },
  wallbox: { entity: 'sensor.wallbox_power', unit: 'kW', soc_entity: 'sensor.car_soc', soc_label: 'Auto' },
  consumers: [
    { entity: 'sensor.washing_machine_power', name: 'Waschmaschine', icon: 'mdi:washing-machine', image: 'ef:waschmaschine', threshold: 5 },
    { entity: 'sensor.fridge_power', name: 'Kühlschrank', icon: 'mdi:fridge-outline', image: 'ef:kuehlschrank', threshold: 10 },
    { entity: 'sensor.tv_power', name: 'TV', icon: 'mdi:television-classic', image: 'ef:tv', threshold: 5,
      hold_action: { action: 'perform-action', perform_action: 'homeassistant.toggle', target: { entity_id: 'switch.tv' } } }
  ]
};

// Linien im Koordinatensystem 400 x H; Richtung = Flussrichtung. dy = Höhe des Bands für Volleinspeise-Anlagen
// Nebenanlagen sitzen in der oberen Reihe: Volleinspeisung links (Linie ins Netz), angeschlossene PV rechts (Linie in die Haupt-PV)
const efLayout = (c) => {
  const fis = (c.feed_in.systems || []).filter((x) => x && x.entity);
  const efNode = (x) => x.node || (x.show_node ? 'pv' : 'none');
  const pvx = (c.pv.extra || []).map((x, i) => ({ x, i, mode: efNode(x) })).filter((o) => o.x && o.x.entity && o.mode !== 'none').slice(0, 1);
  const d = (fis.length || pvx.length) ? 26 : 0;   // mittlere und untere Reihe etwas tiefer, damit oben Platz ist
  const L = {
    pv_home: `M200 145 V ${262 + d}`,
    pv_grid: `M152 50 Q 60 50 60 ${136 + d}`,
    pv_batt: `M248 50 Q 340 50 340 ${136 + d}`,
    grid_batt: `M110 ${180 + d} H 290`,
    batt_grid: `M290 ${180 + d} H 110`,
    grid_home: `M110 ${200 + d} Q 180 ${200 + d} 180 ${262 + d}`,
    batt_home: `M290 ${200 + d} Q 220 ${200 + d} 220 ${262 + d}`,
    home_wb: `M250 ${313 + d} H 290`
  };
  const nodes = [];
  // getrennter Akku (z. B. Garage): eigener Knoten rechts, Haupt-Akku rückt etwas nach links
  const gbi = (c.battery.extra || []).findIndex((x) => x && x.separate && (x.soc_entity || x.charge_entity || x.discharge_entity || x.power_entity));
  const gb = gbi >= 0;
  const battX = gb ? 300 : 340, battW = gb ? 18 : 30;
  if (gb) {
    L.pv_batt = `M248 50 Q 288 50 288 ${136 + d}`;
    L.grid_batt = `M110 ${180 + d} H 270`; L.batt_grid = `M270 ${180 + d} H 110`;
    L.batt_home = `M276 ${200 + d} Q 220 ${200 + d} 220 ${262 + d}`;
    nodes.push({ key: 'bx0', x: 366, w: 17, extra: gbi, kind: 'bx', y: 142.8 + d });
    L.bx_home = `M366 ${258 + d} Q 366 ${272 + d} 336 ${272 + d} H 250`;
  }
  if (fis.length) {
    L.pv_grid = `M152 58 Q 132 58 130 ${104 + d / 2} Q 128 ${144 + d} 104 ${150 + d}`;
    if (c.feed_in.layout === 'separate' && fis.length <= 2) {
      const pos = fis.length === 1 ? [[52, 22]] : [[32, 16], [96, 16]];
      fis.forEach((_, i) => {
        const [cx, w] = pos[i];
        nodes.push({ key: 'fi' + i, x: cx, w, sys: [i], kind: 'fi' });
        L['fi' + i] = cx === 96 ? `M96 ${126} Q 96 ${146 + d} 72 ${140 + d}` : `M${cx} ${w === 16 ? 126 : 134} V ${138 + d}`;
      });
    } else {
      nodes.push({ key: 'fi0', x: 52, w: 22, sys: fis.map((_, i) => i), kind: 'fi' });
      L.fi0 = `M52 136 V ${138 + d}`;
    }
  }
  if (pvx.length) {
    L.pv_batt = gb ? `M248 62 Q 270 62 272 ${104 + d / 2} Q 274 ${144 + d} 288 ${150 + d}` : `M248 62 Q 270 62 270 ${104 + d / 2} Q 272 ${144 + d} 296 ${150 + d}`;
    const toGb = gb && pvx[0].mode === 'battery';
    nodes.push({ key: 'px0', x: toGb ? 366 : 348, w: 22, extra: pvx[0].i, kind: 'px', mode: pvx[0].mode });
    L.px0 = pvx[0].mode === 'battery' ? `M${toGb ? 366 : 348} 136 V ${toGb ? 164 + d : 138 + d}` : 'M318 40 H 250';
    if (pvx[0].mode === 'battery') {
      const sx = toGb ? 336 : 318;
      L.gx_home = `M${sx} 92 C 262 96, 252 ${170 + d}, 246 ${266 + d}`;
      L.gx_grid = `M${sx} 76 C 262 76, 236 ${120 + d}, 236 ${148 + d} Q 236 ${164 + d} 212 ${164 + d} H 112`;
    }
  }
  // Brücken in zwei Ebenen: PV→Haus läuft über die waagerechte Netz-Akku-Linie,
  // die Linien der angeschlossenen PV laufen über alles (auch über PV→Haus)
  const bridge = ['pv_home', 'gx_home', 'gx_grid'];
  const bridgeTop = ['gx_home', 'gx_grid'];
  return { L, H: 420 + d, d, fis, nodes, pvx, gb, gbi, battX, battW, bridge, bridgeTop };
};

const efMerge = (base, over) => {
  const out = Array.isArray(base) ? [...base] : { ...base };
  for (const [k, v] of Object.entries(over || {})) {
    if (v && typeof v === 'object' && !Array.isArray(v) && base[k] && typeof base[k] === 'object' && !Array.isArray(base[k])) {
      out[k] = efMerge(base[k], v);
    } else if (v !== undefined && v !== null && v !== '') {
      out[k] = v;
    } else if (!(k in out)) {
      out[k] = v;
    }
  }
  return out;
};

const efEsc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

class EnergieflussCard extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._offsets = {};
    this._speeds = {};
    this._raf = null;
    this._last = null;
    this._open = null;
    this._consKey = '';
  }

  static getConfigElement() { return document.createElement('energiefluss-card-editor'); }
  static getStubConfig() { return JSON.parse(JSON.stringify(EF_STUB)); }

  setConfig(config) {
    if (!config) throw new Error('Keine Konfiguration');
    this._raw = config;
    this._config = efMerge(EF_DEFAULTS, config);
    this._config.consumers = Array.isArray(config.consumers) ? config.consumers : [];
    if (this._open === null) {
      // Gemerkten Zustand dieses Geräts (Browser/App) verwenden, sonst den Standard aus der Konfiguration
      const saved = this._config.consumers_remember ? this._loadOpen() : null;
      this._open = saved === null ? !!this._config.consumers_open : saved;
    }
    this._consKey = '';
    this._build();
    if (this._hass) this._update();
  }

  // Auf-/Zugeklappt je Gerät: liegt im lokalen Speicher des Browsers bzw. der Companion-App.
  // Schlüssel je Karte (storage_key, sonst Titel der Verbraucherliste), bewusst ohne Adresse der Seite:
  // Die Adresse kann beim Start der App eine andere sein als später (z. B. Dashboard ohne Ansicht).
  _openKey() {
    const c = this._config || {};
    return 'energiefluss-card:open:' + (c.storage_key || c.consumers_title || '');
  }

  _loadOpen() {
    try {
      const v = localStorage.getItem(this._openKey());
      return v === null ? null : v === '1';
    } catch (e) { return null; }
  }

  _saveOpen(open) {
    try { localStorage.setItem(this._openKey(), open ? '1' : '0'); } catch (e) { /* Speicher nicht verfügbar */ }
  }

  set hass(hass) {
    this._hass = hass;
    if (this._config) { this._update(); this._loadRef(); this._loadRunHist(); }
  }

  connectedCallback() { this._startLoop(); }
  disconnectedCallback() { if (this._raf) cancelAnimationFrame(this._raf); this._raf = null; }
  getCardSize() { return 8; }
  getGridOptions() { return { columns: 12, min_columns: 6, rows: 'auto' }; }

  // ---------- Hilfen ----------
  _num(id) {
    if (!id || !this._hass) return 0;
    const v = parseFloat(this._hass.states[id]?.state);
    return isNaN(v) ? 0 : v;
  }
  // Energie in kWh (Wh/MWh werden umgerechnet)
  _kwh(id) {
    if (!id || !this._hass) return NaN;
    const st = this._hass.states[id];
    const v = parseFloat(st?.state);
    if (isNaN(v)) return NaN;
    const u = (st.attributes?.unit_of_measurement || 'kWh').toLowerCase();
    return u === 'wh' ? v / 1000 : u === 'mwh' ? v * 1000 : v;
  }
  _watts(id) {
    if (!id || !this._hass) return 0;
    const st = this._hass.states[id];
    const v = parseFloat(st?.state);
    if (isNaN(v)) return 0;
    const u = (st.attributes?.unit_of_measurement || 'W').toLowerCase();
    if (u === 'kw') return v * 1000;
    if (u === 'mw') return v * 1e6;
    return v;
  }
  _fmtW(w) {
    const c = this._config;
    const a = Math.abs(w);
    if (a >= c.kilo_threshold) return (a / 1000).toFixed(c.decimals_kw).replace('.', ',') + ' kW';
    return Math.round(a) + ' W';
  }
  _fmtState(id) {
    if (!id || !this._hass?.states[id]) return '';
    const st = this._hass.states[id];
    const v = parseFloat(st.state);
    if (isNaN(v)) return '';
    const u = st.attributes?.unit_of_measurement || '';
    return v.toFixed(v >= 100 ? 0 : 1).replace('.', ',') + (u ? ' ' + u : '');
  }

  // ---------- Aufbau ----------
  _build() {
    const c = this._config;
    const lay = this._lay = efLayout(c);
    this._lines = lay.L;
    this._offsets = {}; this._speeds = {};
    // Brücken: darunterliegende Linien werden entlang der Brückenlinie ausgespart (Maske, unabhängig von der Hintergrundfarbe).
    // Ebene 0 = normale Linien, Ebene 1 = Brücke (z. B. PV→Haus), Ebene 2 = Brücke über alles.
    const lvl = (k) => lay.bridgeTop.includes(k) ? 2 : lay.bridge.includes(k) ? 1 : 0;
    const keys = Object.keys(lay.L).filter((k) => lay.L[k]);
    const box = `x="-20" y="-20" width="440" height="${lay.H + 40}"`;
    const mk = (id, from) => { const hs = keys.filter((k) => lvl(k) >= from);
      return hs.length ? `<mask id="${id}" maskUnits="userSpaceOnUse" ${box}><rect ${box} fill="white"/>${hs.map((k) => `<path data-h="${k}" d="${lay.L[k]}" class="halo" style="display:none"/>`).join('')}</mask>` : ''; };
    const m1 = mk('ef-under', 1), m2 = mk('ef-mid', 2);
    const one = (k) => `<g id="g-${k}" style="display:none"><path d="${lay.L[k]}" class="base"/><path id="d-${k}" d="${lay.L[k]}" class="dots"/></g>`;
    const grp = (l, m) => { const ks = keys.filter((k) => lvl(k) === l); return ks.length ? `<g ${m ? `mask="url(#${m})"` : ''}>${ks.map(one).join('')}</g>` : ''; };
    const lines = (m1 || m2 ? `<defs>${m1}${m2}</defs>` : '') + grp(0, m1 && 'ef-under') + grp(1, m2 && 'ef-mid') + grp(2, '');
    const top = (px) => (px / lay.H * 100).toFixed(2);
    const node = (key, x, ypx, n = c[key], w = 30) => `<div class="node${w < 30 ? ' small' : ''}" id="n-${key}" data-node="${key}" style="left:${x}%;top:${top(ypx)}%;width:${w}%">
        ${efPic(n.image, c.icon_style, n.color || (key === 'grid' ? '#FF9999' : ''))}
        <div class="val"></div><div class="sub"></div><div class="sub2"></div><div class="sub3"></div><div class="sub4"></div></div>`;
    const fiNodes = lay.nodes.map((nd) => {
      if (nd.kind === 'bx') {
        const x = c.battery.extra[nd.extra];
        return node(nd.key, nd.x / 4, nd.y, { ...c.battery, ...x, image: x.image || c.battery.image }, nd.w);
      }
      if (nd.kind === 'px') {
        const x = c.pv.extra[nd.extra];
        return node(nd.key, nd.x / 4, 22, { ...c.pv, ...x, image: x.image || c.pv.image }, nd.w);
      }
      const sys = lay.fis[nd.sys[0]];
      const n = nd.sys.length > 1 ? c.feed_in : { ...c.feed_in, ...sys, image: sys.image || c.feed_in.image };
      return node(nd.key, nd.x / 4, 22, n, nd.w);
    }).join('');
    this.shadowRoot.innerHTML = `
      <style>
        :host { display:block; }
        ha-card { ${c.transparent ? 'background:transparent;box-shadow:none;border:none;' : ''} overflow:hidden; }
        .title { font-size:16px; font-weight:500; padding:12px 16px 0; color:var(--primary-text-color); }
        .flow { position:relative; width:100%; aspect-ratio:400/${lay.H}; }
        svg.lines { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; overflow:visible; }
        .base { fill:none; stroke-width:2; opacity:.45; }
        .halo { fill:none; stroke-width:12; stroke:black; stroke-linecap:round; }
        .dots { fill:none; stroke-width:6; stroke-linecap:round; stroke-dasharray:0 14; }
        .node { position:absolute; width:30%; transform:translateX(-50%); text-align:center; cursor:pointer;
                -webkit-tap-highlight-color:transparent; user-select:none; }
        .node img { width:74%; display:block; margin:0 auto; }
        .node svg.mono { width:44%; display:block; margin:12% auto 8%; }
        .ci svg.mono { width:22px; height:22px; flex:none; }
        .val { font-size:16px; font-weight:500; white-space:nowrap; color:var(--primary-text-color); line-height:1.3; }
        .val.idle { color:var(--secondary-text-color); }
        .node.small img { width:64%; } .node.small svg.mono { width:40%; margin:8% auto 4%; } .node.small .val { font-size:13px; } .node.small .sub, .node.small .sub2 { font-size:11px; }
        .sub, .sub2, .sub3, .sub4 { font-size:12px; white-space:nowrap; color:var(--secondary-text-color); line-height:1.35; }
        .sub:empty, .sub2:empty, .sub3:empty, .sub4:empty { display:none; }
        .chip { display:inline-block; color:#1c1c1c; font-weight:500; padding:0 8px; border-radius:6px; }
        .elink { position:absolute; top:1%; left:2%; font-size:12px; color:var(--secondary-text-color); cursor:pointer; opacity:.75; text-decoration:none; z-index:2; }
        .elink:hover { opacity:1; }
        .autarky { position:absolute; top:1%; right:2%; font-size:12px; color:var(--secondary-text-color); }
        .cons { margin:4px 8px 8px; border-top:1px solid var(--divider-color, rgba(127,127,127,.25)); }
        .cons-head { display:flex; align-items:center; justify-content:space-between; padding:10px 6px; cursor:pointer;
                     font-size:14px; color:var(--primary-text-color); user-select:none; -webkit-tap-highlight-color:transparent; }
        .cons-head .info { color:var(--secondary-text-color); font-size:13px; margin-left:6px; }
        .chev { transition:transform .2s; font-size:18px; color:var(--secondary-text-color); }
        .cons.open .chev { transform:rotate(90deg); }
        .cons-body { display:none; grid-template-columns:repeat(2, minmax(0,1fr)); gap:8px; padding:0 4px 4px; }
        .cons.open .cons-body { display:grid; }
        .ci { display:flex; align-items:center; gap:8px; padding:8px 10px; border-radius:10px; cursor:pointer;
              background:var(--secondary-background-color, rgba(127,127,127,.12)); user-select:none; -webkit-tap-highlight-color:transparent; }
        .ci ha-icon { --mdc-icon-size:22px; color:var(--primary-text-color); flex:none; }
        .ci img { width:28px; height:28px; margin:-2px; object-fit:contain; flex:none; }
        .ci .t { min-width:0; }
        .ci .n { font-size:13px; color:var(--primary-text-color); white-space:nowrap; overflow:hidden; text-overflow:ellipsis; }
        .ci .w { font-size:12px; color:var(--secondary-text-color); }
        .ci.idle { opacity:.5; }
        .cons.compact .cons-body { grid-template-columns:repeat(3, minmax(0,1fr)); gap:6px; }
        .cons.compact .ci { padding:6px 8px; gap:6px; border-radius:8px; }
        .cons.compact .ci ha-icon { --mdc-icon-size:18px; }
        .cons.compact .ci svg.mono { width:18px; height:18px; }
        .cons.compact .ci .n { font-size:12px; } .cons.compact .ci .w { font-size:11px; }
        /* feste Spaltenzahl der Verbraucherliste (Einstellung consumers_columns) */
        .cons.cols-2 .cons-body { grid-template-columns:repeat(2, minmax(0,1fr)); }
        .cons.cols-3 .cons-body { grid-template-columns:repeat(3, minmax(0,1fr)); }
        .cons.cols-4 .cons-body { grid-template-columns:repeat(4, minmax(0,1fr)); gap:4px; }
        .cons.cols-4 .ci { padding:6px; gap:5px; border-radius:8px; }
        .cons.cols-4 .ci img { width:22px; height:22px; margin:-1px; }
        .cons.cols-4 .ci ha-icon { --mdc-icon-size:18px; }
        .cons.cols-4 .ci svg.mono { width:18px; height:18px; }
        .cons.cols-4 .ci .n { font-size:11.5px; } .cons.cols-4 .ci .w { font-size:11px; }
        .empty { grid-column:1/-1; font-size:13px; color:var(--secondary-text-color); padding:4px 6px 8px; }
      </style>
      <ha-card>
        ${c.title ? `<div class="title">${efEsc(c.title)}</div>` : ''}
        <div class="flow">
          <svg class="lines" viewBox="0 0 400 ${lay.H}">${lines}</svg>
          <div class="autarky"></div>
          ${c.energy_link ? `<a class="elink" title="Energie-Dashboard öffnen">Energie &#8250;</a>` : ''}
          ${fiNodes}${node('pv', 50, 12.6)}${node('grid', 15, 142.8 + lay.d)}${node('battery', lay.battX / 4, 142.8 + lay.d, c.battery, lay.battW)}${node('home', 50, 268.8 + lay.d)}${node('wallbox', 85, 277.2 + lay.d)}
        </div>
        ${c.consumers.length ? `<div class="cons ${this._open ? 'open' : ''} ${['mono', 'mdi'].includes(c.consumers_icon_style === 'same' ? c.icon_style : c.consumers_icon_style) ? 'compact' : ''} ${['2', '3', '4'].includes(String(c.consumers_columns)) ? 'cols-' + c.consumers_columns : ''}">
          <div class="cons-head"><span><span class="ct">${efEsc(c.consumers_title)}</span><span class="info"></span></span><span class="chev">&#8250;</span></div>
          <div class="cons-body"></div></div>` : ''}
      </ha-card>`;

    this.shadowRoot.querySelectorAll('.node').forEach((el) => {
      this._bindGestures(el, () => this._actionCfg('node', el.dataset.node));
    });
    const head = this.shadowRoot.querySelector('.cons-head');
    if (head) head.addEventListener('click', () => {
      this._open = !this._open;
      this.shadowRoot.querySelector('.cons').classList.toggle('open', this._open);
      if (this._config.consumers_remember) this._saveOpen(this._open);
    });
    const body = this.shadowRoot.querySelector('.cons-body');
    if (body) this._bindGestures(body, (e) => {
      const el = e.target.closest('.ci');
      return el ? this._actionCfg('cons', +el.dataset.idx) : null;
    });
    this._startLoop();
  }

  // ---------- Aktionen (tap / hold / double_tap wie in HA üblich) ----------
  _actionCfg(kind, key) {
    if (kind === 'node' && key.startsWith('bx')) {
      const x = this._config.battery.extra[this._lay.gbi];
      return { entity: x.soc_entity || x.discharge_entity || x.power_entity, tap_action: x.tap_action || { action: 'more-info' }, hold_action: { action: 'none' }, double_tap_action: { action: 'none' } };
    }
    if (kind === 'node' && key.startsWith('px')) {
      const x = this._config.pv.extra[this._lay.nodes.find((n) => n.key === key).extra];
      return { entity: x.entity, tap_action: x.tap_action || { action: 'more-info' }, hold_action: x.hold_action || { action: 'none' }, double_tap_action: x.double_tap_action || { action: 'none' } };
    }
    if (kind === 'node' && key.startsWith('fi')) {
      const nd = this._lay.nodes.find((x) => x.key === key);
      const sys = this._lay.fis[nd.sys[0]];
      const n = nd.sys.length > 1 ? this._config.feed_in : sys;
      return { entity: sys.entity, tap_action: n.tap_action || { action: 'more-info' }, hold_action: n.hold_action || { action: 'none' }, double_tap_action: n.double_tap_action || { action: 'none' } };
    }
    if (kind === 'node') {
      const n = this._config[key];
      const entity = key === 'battery' ? (n.soc_entity || n.discharge_entity || n.power_entity) : (n.entity || n.import_entity);
      const tap = n.tap_action || (n.navigation_path ? { action: 'navigate', navigation_path: n.navigation_path } : { action: 'more-info' });
      return { entity, tap_action: tap, hold_action: n.hold_action || { action: 'none' }, double_tap_action: n.double_tap_action || { action: 'none' } };
    }
    const cs = this._config.consumers[key];
    if (!cs) return null;
    const hold = cs.hold_action || (cs.switch_entity
      ? { action: 'perform-action', perform_action: 'homeassistant.toggle', target: { entity_id: cs.switch_entity } }
      : { action: 'none' });
    return { entity: cs.entity, tap_action: cs.tap_action || { action: 'more-info' }, hold_action: hold, double_tap_action: cs.double_tap_action || { action: 'none' } };
  }
  _fireAction(cfg, action) {
    if (!cfg) return;
    const a = cfg[action + '_action'];
    if (!a || a.action === 'none') return;
    if (action === 'hold' && navigator.vibrate) navigator.vibrate(30);
    this.dispatchEvent(new CustomEvent('hass-action', { bubbles: true, composed: true, detail: { config: cfg, action } }));
  }
  _bindGestures(el, getCfg) {
    let timer = null, held = false, lastTap = 0, tapTimer = null, startX = 0, startY = 0;
    el.addEventListener('pointerdown', (e) => {
      const cfg = getCfg(e); if (!cfg) return;
      held = false; startX = e.clientX; startY = e.clientY;
      timer = setTimeout(() => { held = true; this._fireAction(cfg, 'hold'); }, 500);
    });
    const cancel = () => { clearTimeout(timer); timer = null; };
    el.addEventListener('pointermove', (e) => { if (Math.abs(e.clientX - startX) > 10 || Math.abs(e.clientY - startY) > 10) cancel(); });
    el.addEventListener('pointerup', cancel);
    el.addEventListener('pointerleave', cancel);
    el.addEventListener('pointercancel', cancel);
    el.addEventListener('contextmenu', (e) => e.preventDefault());
    el.addEventListener('click', (e) => {
      const cfg = getCfg(e); if (!cfg) return;
      if (held) { held = false; return; }
      const dbl = cfg.double_tap_action && cfg.double_tap_action.action !== 'none';
      if (!dbl) { this._fireAction(cfg, 'tap'); return; }
      const now = Date.now();
      if (now - lastTap < 280) { clearTimeout(tapTimer); lastTap = 0; this._fireAction(cfg, 'double_tap'); return; }
      lastTap = now;
      tapTimer = setTimeout(() => { lastTap = 0; this._fireAction(cfg, 'tap'); }, 280);
    });
  }

  // ---------- Berechnung ----------
  _flows() {
    const c = this._config;
    const toBatt = (x) => (x.node || (x.show_node ? 'pv' : 'none')) === 'battery';
    const pvList = [c.pv, ...(c.pv.extra || []).filter((x) => x && !toBatt(x))].filter((x) => x && x.entity);
    const gpv = (c.pv.extra || []).filter((x) => x && x.entity && toBatt(x)).reduce((a, x) => a + Math.max(this._watts(x.entity), 0), 0);
    const pvEach = pvList.map((x) => Math.max(this._watts(x.entity), 0));
    const pv = pvEach.reduce((a, b) => a + b, 0);
    let imp, exp;
    if (c.grid.import_entity || c.grid.export_entity) {
      imp = Math.max(this._watts(c.grid.import_entity), 0);
      exp = Math.max(this._watts(c.grid.export_entity), 0);
    } else {
      const g = this._watts(c.grid.entity) * (c.grid.invert ? -1 : 1);
      imp = Math.max(g, 0); exp = Math.max(-g, 0);
    }
    const bPow = (x) => {
      if (x.charge_entity || x.discharge_entity) return { bc: Math.max(this._watts(x.charge_entity), 0), bd: Math.max(this._watts(x.discharge_entity), 0) };
      const b = this._watts(x.power_entity) * (x.invert ? -1 : 1);
      return { bd: Math.max(b, 0), bc: Math.max(-b, 0) };
    };
    const gbCfg = this._lay?.gb ? c.battery.extra[this._lay.gbi] : null;
    const batts = [c.battery, ...(c.battery.extra || []).filter((x) => x !== gbCfg)].filter((x) => x && (x.soc_entity || x.charge_entity || x.discharge_entity || x.power_entity));
    const battEach = batts.map(bPow);
    const gbp = gbCfg ? bPow(gbCfg) : { bc: 0, bd: 0 };
    const bc = battEach.reduce((a, b) => a + b.bc, 0), bd = battEach.reduce((a, b) => a + b.bd, 0);
    const fis = (c.feed_in.systems || []).filter((x) => x && x.entity);
    const fiEach = fis.map((x) => Math.max(this._watts(x.entity), 0));
    const fi = fiEach.reduce((a, b) => a + b, 0);
    const home = Math.max(this._watts(c.home.entity), 0);
    let wb = c.wallbox.entity ? this._num(c.wallbox.entity) : 0;
    if (c.wallbox.unit === 'kW') wb *= 1000;
    wb = Math.max(wb, 0);

    // Reihenfolge: PV deckt zuerst das Haus, dann Akkus, Rest ins Netz. Akkus teilen sich den Bedarf anteilig.
    const f = {};
    const gTarget = gbCfg ? gbp.bc : bc;                  // Akku, den die angeschlossene PV lädt
    const gToB = Math.min(gpv, gTarget);
    let gSur = gpv - gToB;                                 // Überschuss der angeschlossenen PV
    const bcMain = gbCfg ? bc : Math.max(bc - gToB, 0);
    f.pv_home = Math.min(pv, home);
    let need = home - f.pv_home;
    f.gx_home = Math.min(gSur, need); need -= f.gx_home; gSur -= f.gx_home;
    let rest = pv - f.pv_home;
    f.pv_batt = Math.min(rest, bcMain); rest -= f.pv_batt;
    f.pv_grid = Math.min(rest, exp);
    f.gx_grid = Math.min(gSur, Math.max(exp - f.pv_grid, 0));
    const dis = bd + gbp.bd, toHome = Math.min(dis, need);
    f.batt_home = dis > 0 ? toHome * bd / dis : 0;
    f.bx_home = dis > 0 ? toHome * gbp.bd / dis : 0;
    need -= toHome;
    f.grid_home = Math.min(imp, need);
    f.grid_batt = Math.min(Math.max(bcMain - f.pv_batt, 0), Math.max(imp - f.grid_home, 0));
    f.batt_grid = Math.min(Math.max(bd - f.batt_home, 0), Math.max(exp - f.pv_grid - f.gx_grid, 0));
    f.home_wb = wb;
    (this._lay?.nodes || []).forEach((nd) => {
      if (nd.kind === 'bx') return;
      f[nd.key] = nd.kind === 'px' ? (nd.mode === 'battery' ? gToB : Math.max(this._watts(c.pv.extra[nd.extra].entity), 0)) : nd.sys.reduce((a, i) => a + (fiEach[i] || 0), 0);
    });
    return { f, pv, imp, exp, bc, bd, home, wb, pvList, pvEach, batts, battEach, fis, fiEach, fi, gbCfg, gbp };
  }

  _speed(p) {
    // Tempo relativ zum Bezugswert: übliche Höchstleistung der letzten 12 Monate (Langzeitstatistik) oder fester Wert.
    // Logarithmisch zwischen 50 W (langsam) und Bezugswert (schnell), damit 300 W, 1 kW und 5 kW klar unterscheidbar sind.
    const ref = Math.max((this._config.speed_reference === 'auto' && this._ref) || this._config.speed_max_w || 10000, 500);
    const r = Math.min(Math.max(Math.log(Math.max(p, 50) / 50) / Math.log(ref / 50), 0), 1.15);
    return this._config.speed * 3 * Math.pow(14, r);   // ca. 3 bis 42 Einheiten/s
  }

  // ---------- Restlaufzeit und Ladezeit Akku ----------
  // Entlade- und Ladeleistung werden je über die laufende Phase gemittelt (höchstens runtime_window Minuten),
  // damit kurze Spitzen (Wasserkocher, Herd, Wolken) die Anzeige nicht hin- und herspringen lassen.
  // Verlauf kommt beim Start aus dem HA-Recorder, danach aus den Live-Werten.
  // Reihen: d = Entladen, c = Laden, pv = PV-Leistung (nur live, für den PV-Anteil beim Laden).
  _runBatts() {
    const c = this._config, gbCfg = this._lay?.gb ? c.battery.extra[this._lay.gbi] : null;
    return [c.battery, ...(c.battery.extra || []).filter((x) => x !== gbCfg)]
      .filter((x) => x && (x.charge_entity || x.discharge_entity || x.power_entity));
  }
  _runWin() { return Math.min(Math.max(+this._config.battery.runtime_window || 60, 5), 240) * 60000; }
  _runOn() { const c = this._config, b = c.battery; return !!(b.show_runtime || b.show_chargetime || (c.wallbox.show_chargetime && c.wallbox.soc_entity)); }

  async _loadRunHist() {
    const c = this._config, h = this._hass;
    if (!h || !this._runOn() || this._runLoading) return;
    const rs = this._ser?.d;
    // neu laden beim Start und nach einer Pause ohne Werte (z. B. App im Hintergrund)
    if (rs && rs.length && Date.now() - rs[rs.length - 1][0] < 3 * 60000) return;
    if (this._runTry && Date.now() - this._runTry < 60000) return;
    this._runTry = Date.now();
    const bs = this._runBatts();
    const wbE = c.wallbox.show_chargetime && c.wallbox.soc_entity ? c.wallbox.entity : '', homeE = wbE ? c.home.entity : '';
    const ids = [...new Set([...bs.flatMap((x) => (x.charge_entity || x.discharge_entity) ? [x.discharge_entity, x.charge_entity] : [x.power_entity]), wbE, homeE]
      .filter((x) => x && h.states[x]))];
    if (!ids.length) return;
    this._runLoading = true;
    try {
      const start = new Date(Date.now() - this._runWin() - 60000).toISOString();
      const res = await h.callWS({ type: 'history/history_during_period', start_time: start, entity_ids: ids,
        minimal_response: true, no_attributes: true, significant_changes_only: false });
      // je Entität: Stufenfunktion [Zeit, Watt]
      const ser = {};
      for (const id of ids) {
        const u = (h.states[id]?.attributes?.unit_of_measurement || (id === wbE && c.wallbox.unit === 'kW' ? 'kW' : 'W')).toLowerCase();
        const f = u === 'kw' ? 1000 : u === 'mw' ? 1e6 : 1;
        ser[id] = (res?.[id] || []).map((e) => {
          const t = e.lu != null ? e.lu * 1000 : e.lc != null ? e.lc * 1000 : Date.parse(e.last_updated || e.last_changed);
          const v = parseFloat(e.s ?? e.state);
          return [t, isNaN(v) ? 0 : v * f];
        }).filter((x) => !isNaN(x[0])).sort((a, b) => a[0] - b[0]);
      }
      const times = [...new Set(Object.values(ser).flatMap((a) => a.map((x) => x[0])))].sort((a, b) => a - b);
      const at = (arr, t) => { if (!arr) return 0; let v = 0; for (const x of arr) { if (x[0] > t) break; v = x[1]; } return v; };
      const sum = (t, dir) => bs.reduce((a, x) => {
        if (x.charge_entity || x.discharge_entity) return a + Math.max(at(ser[dir === 'd' ? x.discharge_entity : x.charge_entity], t), 0);
        const b = at(ser[x.power_entity], t) * (x.invert ? -1 : 1);
        return a + Math.max(dir === 'd' ? b : -b, 0);
      }, 0);
      this._ser = this._ser || {};
      const one = (id) => (ser[id] || []).map(([t, v]) => [t, Math.max(v, 0)]);
      const build = { d: () => times.map((t) => [t, sum(t, 'd')]), c: () => times.map((t) => [t, sum(t, 'c')]),
        wb: () => one(wbE), home: () => one(homeE) };
      for (const k of Object.keys(build)) {
        if ((k === 'wb' || k === 'home') && !wbE) continue;
        const out = build[k]();
        // Live-Werte, die während des Ladens schon kamen, hinten anhängen
        const live = (this._ser[k] || []).filter((x) => x[0] > (out.length ? out[out.length - 1][0] : 0));
        this._ser[k] = [...out, ...live];
      }
      this._update();
    } catch (e) { /* ohne Verlauf: Mittelung nur aus Live-Werten */ } finally { this._runLoading = false; }
  }

  // Live-Wert an Reihe k anhängen und den Mittelwert der laufenden Phase liefern
  _rate(k, v) {
    const now = Date.now(), win = this._runWin(), TH = 50, GAP = 5 * 60000;
    this._ser = this._ser || {};
    const s = this._ser[k] || (this._ser[k] = []);
    const last = s[s.length - 1];
    if (!last || Math.abs(last[1] - v) > 1 || now - last[0] > 30000) s.push([now, v]);
    while (s.length > 2 && s[1][0] < now - win) s.shift();
    // Beginn der laufenden Phase suchen; kurze Unterbrechungen (< 5 min) zählen mit
    let start = s[s.length - 1][0], gapFrom = null;
    for (let i = s.length - 1; i >= 0; i--) {
      const [t, w] = s[i], end = i + 1 < s.length ? s[i + 1][0] : now;
      if (w >= TH) { start = t; gapFrom = null; continue; }
      if (gapFrom === null) gapFrom = end;
      if (gapFrom - t > GAP) break;
    }
    start = Math.max(start, now - win);
    let e = 0, dur = 0;
    for (let i = 0; i < s.length; i++) {
      const a = Math.max(s[i][0], start), b = i + 1 < s.length ? s[i + 1][0] : now;
      if (b > a) { e += s[i][1] * (b - a); dur += b - a; }
    }
    return dur > 60000 ? e / dur : v;
  }

  // Angezeigte Uhrzeit beruhigen: kleine Abweichungen (< 20 min) übergehen,
  // größere erst übernehmen, wenn sie 3 Minuten lang bestehen.
  _steady(k, t) {
    const now = Date.now(), st = (this._stdy = this._stdy || {})[k];
    if (!st || now - st.seen > 10 * 60000) { this._stdy[k] = { t, seen: now, diff: null }; return t; }
    st.seen = now;
    if (Math.abs(t - st.t) < 20 * 60000) { st.diff = null; return st.t; }
    if (!st.diff) st.diff = now;
    if (now - st.diff >= 3 * 60000) { st.t = t; st.diff = null; }
    return st.t;
  }
  _hm(t) { return new Date(t).toLocaleTimeString('de-DE', { hour: '2-digit', minute: '2-digit' }); }

  // Ladezeit des Fahrzeugs bis zum Ladeziel. Lädt es überwiegend aus PV, wird geprüft, ob die Sonne dafür reicht:
  // PV-Prognose (Resttag heute) minus erwarteter Hausverbrauch (ohne Wallbox) bis Sonnenuntergang minus Bedarf des Hausakkus.
  _carText(wb, home, imp, pv, battNeed) {
    const c = this._config, w = c.wallbox, h = this._hass;
    const rate = this._rate('wb', wb), homeAvg = this._rate('home', Math.max(home - wb, 0));
    if (!w.show_chargetime || !w.soc_entity || wb < 100) return '';
    const soc = parseFloat(h.states[w.soc_entity]?.state);
    const capS = w.capacity_entity ? parseFloat(h.states[w.capacity_entity]?.state) : NaN;
    const cap = !isNaN(capS) && capS > 0 ? capS : +w.capacity_kwh || 0;
    const tgS = w.target_entity ? parseFloat(h.states[w.target_entity]?.state) : NaN;
    const target = Math.min(Math.max(!isNaN(tgS) && tgS > 0 ? tgS : +w.charge_target_soc || 100, 1), 100);
    if (isNaN(soc) || cap <= 0) return '';
    const need = Math.max(target - soc, 0) / 100 * cap;
    if (need < 0.1) return '';
    const hrs = need * 1000 / Math.max(rate, 100);
    const eta = Date.now() + hrs * 3600000;
    // Lademodus (z. B. aus EVCC): off = keine Anzeige, now = sofort mit voller Leistung,
    // minpv = PV, bei zu wenig Sonne mit Mindestleistung weiter, pv = nur Überschuss (endet abends)
    const mRaw = w.mode_entity ? String(h.states[w.mode_entity]?.state || '').toLowerCase().replace(/\s/g, '') : '';
    // „Smart“ (EVCC) lädt aus PV-Überschuss wie „pv“; unbekannte Modi werden wie ohne Modus behandelt (Erkennung über den Netzbezug)
    const known = { off: 'off', now: 'now', minpv: 'minpv', pv: 'pv', aus: 'off', schnell: 'now', sofort: 'now', fast: 'now',
      'min+pv': 'minpv', solar: 'pv', smart: 'pv' };
    let mode = known[mRaw] || '';
    if (mode === 'off') return '';
    const st = (id) => (id ? h.states[id]?.state : undefined);
    const isOn = (id) => { const v = String(st(id) ?? '').toLowerCase().trim();
      return !!v && !['off', 'aus', 'false', '0', 'none', 'unknown', 'unavailable', 'nein', 'no'].includes(v); };
    const fmt = (t) => (target < 100 ? `${Math.round(target)} % ` : 'voll ') + 'ca. ' + this._hm(this._steady('wb', Math.round(t / 600000) * 600000));
    // Ladeplan aktiv (z. B. EVCC): geplantes Ende anzeigen
    if (w.plan_active_entity && isOn(w.plan_active_entity)) {
      const pe = Date.parse(st(w.plan_end_entity) || '');
      if (!isNaN(pe) && pe > Date.now()) return 'Plan ' + fmt(pe);
    }
    // günstiges Netzladen aktiv: lädt aus dem Netz wie „sofort“
    if (w.grid_cost_entity && isOn(w.grid_cost_entity)) mode = 'now';
    // „Dauerhaft laden“ / „Mit min. laden“ (EVCC: off / on / once = nur dieser Ladevorgang): bei PV-Laden ohne Sonne mit Mindestleistung weiter
    if (mode === 'pv' && w.always_entity && isOn(w.always_entity)) mode = 'minpv';
    // Sonnenanteil (%): 0 = lädt voll aus dem Netz, sonst wird jede kWh PV um den Netzanteil ergänzt
    const shS = parseFloat(st(w.solar_share_entity));
    const share = !isNaN(shS) ? Math.min(Math.max(shS, 0), 100) / 100 : 1;
    if (share === 0 && (mode === 'pv' || mode === 'minpv')) mode = 'now';
    // Mindestleistung aus Mindeststrom × Phasen × 230 V, sonst fester Wert
    const mA = parseFloat(st(w.min_current_entity)), ph = parseFloat(st(w.phases_entity));
    const minP = !isNaN(mA) && mA > 0 ? mA * 230 * (!isNaN(ph) && ph > 0 ? ph : 1) : +w.min_power_w || 1400;
    const pvMode = mode === 'pv' || mode === 'minpv' || (!mode && imp < rate * 0.5 && pv > 200);
    if (pvMode && mode !== 'now') {
      const set = Date.parse(h.states['sun.sun']?.attributes?.next_setting || '');
      const toSet = !isNaN(set) && set - Date.now() < 18 * 3600000 ? Math.max(set - Date.now(), 0) / 3600000 : null;
      let avail = null;
      const fc = c.battery.forecast_entity ? h.states[c.battery.forecast_entity] : null;
      if (fc && !isNaN(parseFloat(fc.state))) {
        const u = (fc.attributes?.unit_of_measurement || 'kWh').toLowerCase();
        const kwh = parseFloat(fc.state) / (u === 'wh' ? 1000 : u === 'mwh' ? 0.001 : 1);
        avail = Math.max(kwh - homeAvg / 1000 * (toSet ?? 0) - battNeed, 0) / share;
        if (toSet !== null) avail = Math.min(avail, rate / 1000 * toSet);
      } else if (toSet !== null && eta > set) avail = rate / 1000 * toSet * 0.5;
      if (avail !== null && avail < need) {
        if (mode === 'minpv' && toSet !== null) {
          // Rest nach Sonnenuntergang mit Mindestleistung
          const t2 = set + (need - avail) * 1000 / Math.max(minP, 100) * 3600000;
          if (t2 - Date.now() > 24 * 3600000) return 'voll in über 24 h';
          return fmt(t2);
        }
        const reach = Math.min(Math.max(Math.floor((soc + avail / cap * 100) / 5) * 5, Math.round(soc)), target);
        return `heute ca. ${reach} %`;
      }
    }
    if (hrs > 24) return 'voll in über 24 h';
    return fmt(eta);
  }

  // Ladezeit bis zum Ziel-Ladestand. Beim Laden aus PV wird geprüft, ob die Sonne dafür noch reicht:
  // mit PV-Prognose (Resttag heute) über den PV-Anteil, der gerade im Akku landet, sonst über den Sonnenuntergang.
  _chargeText(bInfo, bc, pv) {
    const c = this._config, b = c.battery;
    const rate = this._rate('c', bc), pvAvg = this._rate('pv', pv);
    if (!b.show_chargetime || bc < 50) return '';
    const target = Math.min(Math.max(+b.charge_target_soc || 100, 1), 100);
    const need = bInfo.reduce((a, x) => a + (x.has ? Math.max(target - x.soc, 0) / 100 * x.cap : 0), 0); // kWh
    const capSum = bInfo.reduce((a, x) => a + (x.has ? x.cap : 0), 0);
    if (capSum <= 0 || need < 0.05) return '';
    const h = need * 1000 / Math.max(rate, 50);
    const eta = Date.now() + h * 3600000;
    const fromPv = pvAvg >= rate * 0.5;
    if (fromPv) {
      // verfügbare PV-Energie für den Akku bis zum Abend schätzen
      let avail = null;
      const fc = b.forecast_entity ? this._hass.states[b.forecast_entity] : null;
      if (fc && !isNaN(parseFloat(fc.state))) {
        const u = (fc.attributes?.unit_of_measurement || 'kWh').toLowerCase();
        const kwh = parseFloat(fc.state) / (u === 'wh' ? 1000 : u === 'mwh' ? 0.001 : 1);
        avail = kwh * Math.min(rate / Math.max(pvAvg, 1), 1);
      } else {
        const set = Date.parse(this._hass.states['sun.sun']?.attributes?.next_setting || '');
        if (!isNaN(set) && set - Date.now() < 18 * 3600000 && eta > set) avail = rate / 1000 * Math.max(set - Date.now(), 0) / 3600000 * 0.5;
      }
      if (avail !== null && avail < need) {
        const now = bInfo.reduce((a, x) => a + (x.has ? x.soc * x.cap : 0), 0) / capSum;
        const reach = Math.min(Math.max(Math.floor((now + avail / capSum * 100) / 5) * 5, Math.round(now)), target);
        return `heute ca. ${reach} %`;
      }
    }
    if (h > 24) return 'voll in über 24 h';
    const t = this._steady('c', Math.round(eta / 600000) * 600000);
    return (target < 100 ? `${target} % ` : 'voll ') + 'ca. ' + this._hm(t);
  }

  // Übliche Höchstwerte aus der HA-Langzeitstatistik (Median der Monatsmaxima je Sensor, davon das Maximum)
  async _loadRef() {
    const c = this._config, h = this._hass;
    if (!h || c.speed_reference !== 'auto' || this._refLoading || (this._refAt && Date.now() - this._refAt < 6 * 3600000)) return;
    this._refLoading = true;
    try {
      const ids = [c.pv.entity, ...(c.pv.extra || []).map((x) => x.entity), c.grid.entity, c.grid.import_entity, c.grid.export_entity,
        c.battery.charge_entity, c.battery.discharge_entity, c.battery.power_entity, c.home.entity, c.wallbox.entity,
        ...(c.feed_in.systems || []).map((x) => x.entity)].filter((x) => x && h.states[x]);
      if (!ids.length) return;
      const start = new Date(Date.now() - 365 * 86400000).toISOString();
      const res = await h.callWS({ type: 'recorder/statistics_during_period', start_time: start, period: 'month', statistic_ids: [...new Set(ids)], types: ['max'] });
      let ref = 0;
      for (const [id, rows] of Object.entries(res || {})) {
        const u = (h.states[id]?.attributes?.unit_of_measurement || 'W').toLowerCase();
        const f = u === 'kw' ? 1000 : u === 'mw' ? 1e6 : 1;
        const m = rows.map((r) => Math.abs(r.max ?? 0) * f).filter((v) => v > 0).sort((a, b) => a - b);
        if (m.length) ref = Math.max(ref, m[Math.floor(m.length / 2)]);
      }
      if (ref > 0) this._ref = ref;
      this._refAt = Date.now();
    } catch (e) { this._refAt = Date.now(); } finally { this._refLoading = false; }
  }

  // ---------- Aktualisierung ----------
  _update() {
    const c = this._config, r = this.shadowRoot;
    if (!r.querySelector('.flow')) return;
    const { f, pv, imp, exp, bc, bd, home, wb, pvList, pvEach, batts, fis, fiEach, fi, gbCfg, gbp } = this._flows();
    const kw = (w) => (w / 1000).toFixed(1).replace('.', ',');
    const sumKwh = (ids) => { let t = 0, any = false; ids.forEach((id) => { const v = this._kwh(id); if (!isNaN(v)) { t += v; any = true; } }); return any ? t : NaN; };
    const fmtKwh = (v) => isNaN(v) ? '' : v.toFixed(v >= 100 ? 0 : 1).replace('.', ',') + ' kWh';
    const col = {
      pv_home: c.pv.color, pv_batt: c.pv.color, pv_grid: c.grid.color_export, batt_grid: c.grid.color_export,
      grid_batt: c.grid.color_import, grid_home: c.grid.color_import, batt_home: c.battery.color, home_wb: c.wallbox.color,
      fi0: c.grid.color_export, fi1: c.grid.color_export, px0: c.pv.color, bx_home: c.battery.color, gx_home: c.pv.color, gx_grid: c.grid.color_export
    };
    const wbVisible = c.wallbox.entity && (c.wallbox.mode === 'always' || (c.wallbox.mode === 'auto' && wb > 0));
    for (const k of Object.keys(this._lines)) {
      const p = f[k] || 0;
      const on = p >= c.threshold && (k !== 'home_wb' || wbVisible);
      const g = r.getElementById('g-' + k);
      g.style.display = on ? '' : 'none';
      r.querySelectorAll(`[data-h="${k}"]`).forEach((hl) => { hl.style.display = on ? '' : 'none'; });
      if (on) g.querySelectorAll('path').forEach((pa) => pa.setAttribute('stroke', col[k]));
      this._speeds[k] = on ? this._speed(p) : 0;
    }

    // PV
    const pvDay = pvList.length > 1 ? fmtKwh(sumKwh(pvList.map((x) => x.secondary_entity).filter(Boolean))) : this._fmtState(c.pv.secondary_entity);
    const pvBreak = (pvList.length > 1 && c.pv.show_breakdown) ? pvList.map((x, i) => `${x.name || 'PV ' + (i + 1)} ${kw(pvEach[i])}`).join(' · ') + ' kW' : '';
    this._setNode('pv', this._fmtW(pv), pv < c.threshold, pvDay ? 'heute ' + pvDay : '', pvBreak);
    // Volleinspeisung
    (this._lay.nodes || []).forEach((nd) => {
      if (nd.kind === 'bx') return;
      if (nd.kind === 'px') {
        const x = c.pv.extra[nd.extra], w = Math.max(this._watts(x.entity), 0), d = this._fmtState(x.secondary_entity);
        this._setNode(nd.key, this._fmtW(w), w < c.threshold, efEsc(x.name || 'PV ' + (nd.extra + 2)), d ? 'heute ' + efEsc(d) : '', true);
        return;
      }
      const p = nd.sys.reduce((a, i) => a + (fiEach[i] || 0), 0);
      const day = fmtKwh(sumKwh(nd.sys.map((i) => fis[i].secondary_entity).filter(Boolean)));
      if (nd.sys.length > 1) {
        const br = c.feed_in.show_breakdown ? nd.sys.map((i) => `${fis[i].name || 'Anlage ' + (i + 1)} ${kw(fiEach[i])}`).join(' · ') + ' kW' : '';
        this._setNode(nd.key, this._fmtW(p), p < c.threshold, day ? 'heute ' + day : efEsc(c.feed_in.name), efEsc(br), true);
      } else {
        const sys = fis[nd.sys[0]];
        this._setNode(nd.key, this._fmtW(p), p < c.threshold, efEsc(sys.name || 'Anlage ' + (nd.sys[0] + 1)), day, true);
      }
    });
    // Netz
    const gridNet = imp - exp;
    const gTxt = Math.abs(gridNet) < c.threshold ? c.grid.name : (gridNet > 0 ? 'Bezug' : 'Einspeisung');
    const gCol = Math.abs(gridNet) < c.threshold ? '' : (gridNet > 0 ? c.grid.color_import : c.grid.color_export);
    const s1 = this._fmtState(c.grid.secondary_entity), s2 = this._fmtState(c.grid.secondary_entity_2);
    this._setNode('grid', this._fmtW(gridNet), Math.abs(gridNet) < c.threshold,
      `<span style="color:${gCol || 'inherit'}">${efEsc(gTxt)}</span>`,
      (s1 || s2) ? `heute ${s2 ? `<span style="color:${c.grid.color_export};opacity:.75">&#8592;&#8239;${efEsc(s1 ? s2.replace(/ kWh$/, '') : s2)}</span>` : ''}${s1 && s2 ? ' &nbsp;' : ''}${s1 ? `<span style="color:${c.grid.color_import};opacity:.75">&#8594;&#8239;${efEsc(s1)}</span>` : ''}` : '', true);
    if (fis.length && (c.grid.show_feed_in || c.grid.show_total)) {
      const ng = r.getElementById('n-grid'), sp = (t) => `<span style="color:${c.grid.color_export};opacity:.85">${t}</span>`;
      const tot = exp + fi - imp;
      ng.querySelector('.sub3').innerHTML = c.grid.show_feed_in ? sp(`Volleinspeisung ${this._fmtW(fi)}`) : '';
      ng.querySelector('.sub4').innerHTML = c.grid.show_total ? sp(`gesamt ${tot >= 0 ? '&#8592;' : '&#8594;'}&#8239;${this._fmtW(tot)}`) : '';
    }
    // Akku
    // Ladestand: nach Kapazität gewichtet; Restlaufzeit aus nutzbarer Energie aller Akkus
    const bInfo = batts.map((x) => ({ name: x.name, soc: this._num(x.soc_entity), cap: x.capacity_kwh ?? c.battery.capacity_kwh, min: x.min_soc ?? c.battery.min_soc, has: !!x.soc_entity }));
    const capSum = bInfo.reduce((a, b) => a + (b.has ? b.cap : 0), 0);
    const soc = capSum > 0 ? bInfo.reduce((a, b) => a + (b.has ? b.soc * b.cap : 0), 0) / capSum : this._num(c.battery.soc_entity);
    const usable = bInfo.reduce((a, b) => a + (b.has ? Math.max(b.soc - b.min, 0) / 100 * b.cap : 0), 0);
    const bw = Math.max(bc, bd);
    let run = '';
    const rate = this._runOn() ? this._rate('d', bd) : bd;
    if (c.battery.show_runtime && bd >= 50 && usable > 0) {
      const h = usable * 1000 / Math.max(rate, 50);
      if (h > 24) run = 'reicht über 24 h';
      else run = 'bis ' + this._hm(this._steady('d', Math.round((Date.now() + h * 3600000) / 600000) * 600000));
    }
    const chg = this._runOn() ? this._chargeText(bInfo, bc, pv) : '';
    if (!run) run = chg;
    const chip = capSum > 0 ? `<span class="chip" style="background:${c.battery.color}">${Math.round(soc)} %</span>` : '';
    this._setNode('battery', this._fmtW(bw), bw < c.threshold, chip, efEsc(run), true);
    r.getElementById('n-battery').querySelector('.sub3').textContent = (batts.length > 1 && c.battery.show_breakdown)
      ? bInfo.map((b, i) => `${b.name || 'Akku ' + (i + 1)} ${Math.round(b.soc)} %`).join(' · ') : '';
    if (gbCfg) {
      const gsoc = this._num(gbCfg.soc_entity), gw = Math.max(gbp.bc, gbp.bd);
      const gchip = gbCfg.soc_entity ? `<span class="chip" style="background:${c.battery.color}">${Math.round(gsoc)} %</span>` : '';
      this._setNode('bx0', this._fmtW(gw), gw < c.threshold, gchip, efEsc(gbCfg.name || 'Akku 2'), true);
    }
    // Haus
    const hs = this._fmtState(c.home.secondary_entity);
    this._setNode('home', this._fmtW(home), home < c.threshold, hs ? 'heute ' + efEsc(hs) : '', '', true);
    // Wallbox
    const wn = r.getElementById('n-wallbox');
    wn.style.display = wbVisible ? '' : 'none';
    if (wbVisible) {
      const wsoc = c.wallbox.soc_entity ? this._hass.states[c.wallbox.soc_entity]?.state : null;
      const wTxt = (wsoc !== null && wsoc !== undefined && !isNaN(parseFloat(wsoc))) ? `${efEsc(c.wallbox.soc_label)} ${Math.round(parseFloat(wsoc))} %` : '';
      // Hausakku hat nur bis zur Prioritätsgrenze Vorrang (z. B. EVCC „Haus hat Priorität“), sonst bis zum Ladeziel
      const prS = c.wallbox.priority_entity ? parseFloat(this._hass.states[c.wallbox.priority_entity]?.state) : NaN;
      const bt = !isNaN(prS) ? Math.min(Math.max(prS, 0), 100) : Math.min(Math.max(+c.battery.charge_target_soc || 100, 1), 100);
      const battNeed = (bc >= 50 || !isNaN(prS)) ? bInfo.reduce((a, x) => a + (x.has ? Math.max(bt - x.soc, 0) / 100 * x.cap : 0), 0) : 0;
      const cTxt = this._runOn() ? this._carText(wb, home, imp, pv, battNeed) : '';
      this._setNode('wallbox', this._fmtW(wb), wb < c.threshold, wTxt, efEsc(cTxt), true);
    }
    // Autarkie
    const el = r.querySelector('.elink');
    if (el && !el._ef) {
      el._ef = true;
      el.addEventListener('click', (ev) => {
        ev.stopPropagation();
        history.pushState(null, '', c.energy_link);
        window.dispatchEvent(new CustomEvent('location-changed', { detail: { replace: false } }));
      });
    }
    const aut = r.querySelector('.autarky');
    if (c.show_autarky) {
      let a = null, label = c.autarky_mode === 'live' ? 'Autarkie' : 'Autarkie (live)';
      if (c.autarky_mode !== 'live') {
        // Tageswert: eigener Sensor oder 1 - Netzbezug heute / Hausverbrauch heute
        if (c.autarky_entity) {
          const v = parseFloat(this._hass.states[c.autarky_entity]?.state);
          if (!isNaN(v)) a = Math.round(v);
        } else {
          const imp = this._kwh(c.grid.secondary_entity), cons = this._kwh(c.home.secondary_entity);
          if (!isNaN(imp) && !isNaN(cons) && cons > 0) a = Math.round(Math.max(0, Math.min(1, 1 - imp / cons)) * 100);
        }
        if (a !== null) label = 'Autarkie heute';
      }
      if (a === null) a = home > 0 ? Math.round((1 - Math.min(f.grid_home, home) / home) * 100) : 100;
      aut.textContent = `${label} ${a} %`;
    } else aut.textContent = '';

    this._updateConsumers();
  }

  _setNode(key, val, idle, sub, sub2, html) {
    const n = this.shadowRoot.getElementById('n-' + key);
    if (!n) return;
    const v = n.querySelector('.val');
    v.textContent = val;
    v.classList.toggle('idle', !!idle);
    const a = n.querySelector('.sub'), b = n.querySelector('.sub2');
    if (html) { a.innerHTML = sub || ''; b.innerHTML = sub2 || ''; } else { a.textContent = sub || ''; b.textContent = sub2 || ''; }
  }

  _updateConsumers() {
    const c = this._config, r = this.shadowRoot;
    const body = r.querySelector('.cons-body');
    if (!body) return;
    let sum = 0, count = 0;
    const rows = [];
    c.consumers.forEach((cs, i) => {
      if (!cs?.entity) return;
      const w = this._watts(cs.entity);
      const active = w >= (cs.threshold ?? 5);
      if (active) { sum += w; count++; }
      if (c.consumers_only_active && !active) return;
      const st = c.consumers_icon_style === 'same' ? c.icon_style : c.consumers_icon_style;
      const pic = (cs.image && st !== 'mdi')
        ? efPic(cs.image, st)
        : `<ha-icon icon="${efEsc(cs.icon || 'mdi:flash')}"></ha-icon>`;
      const name = cs.name || this._hass?.states[cs.entity]?.attributes?.friendly_name || cs.entity;
      rows.push(`<div class="ci ${active ? '' : 'idle'}" data-idx="${i}">${pic}<div class="t"><div class="n">${efEsc(name)}</div><div class="w">${this._fmtW(w)}</div></div></div>`);
    });
    const html = rows.length ? rows.join('') : '<div class="empty">Gerade kein Verbraucher aktiv</div>';
    if (html !== this._consKey) { body.innerHTML = html; this._consKey = html; }
    r.querySelector('.cons-head .info').textContent = `· ${count} aktiv · ${this._fmtW(sum)}`;
  }

  // ---------- Animation ----------
  _startLoop() {
    if (this._raf || !this.isConnected) return;
    const step = (t) => {
      const dt = this._last ? Math.min((t - this._last) / 1000, 0.1) : 0;
      this._last = t;
      const r = this.shadowRoot;
      for (const [k, s] of Object.entries(this._speeds)) {
        if (!s) continue;
        this._offsets[k] = ((this._offsets[k] || 0) - s * dt) % 28;
        const el = r.getElementById('d-' + k);
        if (el) el.style.strokeDashoffset = this._offsets[k];
      }
      this._raf = requestAnimationFrame(step);
    };
    this._raf = requestAnimationFrame(step);
  }
}

